INSERT INTO `d_program_0` VALUES (4,4,1,2,1,1,'于文文「魔方视界」巡回演唱会','于文文','MAO Livehouse北京','https://s21.ax1x.com/2024/12/19/pAOK6R1.jpg',1,'本商品为预售商品，正式开票后将第一时间为您配票','预售期间，由于主办未正式开票，下单后无法立即为您配票。一般于演出前1-2周开票，待正式开票后，请您通过订单详情页或者票夹详情，查看票品信息、取票方式等演出相关信息','https://s21.ax1x.com/2024/12/19/pAOKcxx.png',6,6,'票品为有价票券，非普通商品，其背后承载的文化服务具有时效性，稀缺性等特征，不支持退换。','不支持修改配送电话、地址等信息','须打开【票夹】扫码入场，截图无效。','儿童一律凭票入场','演出开始前，去【订单详情页】提交发票申请。我们会将电子发票发送至您的邮箱。','一个订单对应一个证件；证件支持：护照/台湾居民来往大陆通行证/身份证/港澳居民来往内地通行证','对于异常订购行为，平台有权在订单成立或者生效之后取消相应订单。异常订购行为包括但不限于以下情形：（1）通过同一ID订购超出限购张数的订单。（2）经合理判断认为非真实消费者的下单行为，包括但不限于通过批量相同或虚构的支付账号、收货地址（包括下单时填写及最终实际收货地址）、收件人、电话号码订购超出限购张数的订单。','1.购买前请您提前规划好行程，做好相应准备，以免影响您的正常观演，感谢您的理解和配合。2.若演出受不可抗力影响延期或取消，平台将对演出票订单按照项目官方通知方案进行处理，其他因观演发生的费用需由您自行承担。','约90分钟，仅供参考，最终以现场实际时长为准','提前30-60分钟，仅供参考，最终以现场实际入场为准',NULL,'','','由于安保和版权的原因，大多数演出、展览及比赛场所禁止携带食品、饮料、专业摄录设备、打火机等物品，请您注意现场工作人员和广播的提示，予以配合。','以现场为准,以现场为准',NULL,0,'票品为有价票券，非普通商品，其背后承载的文化服务具有时效性，稀缺性等特征，不支持退换。',0,NULL,0,'本项目不支持自主选座，同一个订单优先连座',1,'通过身份证验票入场',1,'发票开具方：文化传媒发展有限公司',0,1,'2024-04-09 00:00:00','2024-01-08 00:00:00','2024-01-08 00:00:00',1),(8,8,1,2,1,1,'【挪威的森林】伍佰魔性情歌之夜演唱会|从“突然的自我”听到“伤心太平洋”','挪威的森林','WeShow Live','https://s21.ax1x.com/2024/06/06/pkYEs4P.webp',1,'本商品为预售商品，正式开票后将第一时间为您配票','预售期间，由于主办未正式开票，下单后无法立即为您配票。一般于演出前1-2周开票，待正式开票后，请您通过订单详情页或者票夹详情，查看票品信息、取票方式等演出相关信息','https://s21.ax1x.com/2024/06/06/pkYEggS.png',6,6,'票品为有价票券，非普通商品，其背后承载的文化服务具有时效性，稀缺性等特征，不支持退换。','不支持修改配送电话、地址等信息','须打开【票夹】扫码入场，截图无效。','儿童一律凭票入场','演出开始前，去【订单详情页】提交发票申请。我们会将电子发票发送至您的邮箱。','一个订单对应一个证件；证件支持：护照/台湾居民来往大陆通行证/身份证/港澳居民来往内地通行证','对于异常订购行为，平台有权在订单成立或者生效之后取消相应订单。异常订购行为包括但不限于以下情形：（1）通过同一ID订购超出限购张数的订单。（2）经合理判断认为非真实消费者的下单行为，包括但不限于通过批量相同或虚构的支付账号、收货地址（包括下单时填写及最终实际收货地址）、收件人、电话号码订购超出限购张数的订单。','1.购买前请您提前规划好行程，做好相应准备，以免影响您的正常观演，感谢您的理解和配合。2.若演出受不可抗力影响延期或取消，平台将对演出票订单按照项目官方通知方案进行处理，其他因观演发生的费用需由您自行承担。','约90分钟，仅供参考，最终以现场实际时长为准','提前30-60分钟，仅供参考，最终以现场实际入场为准',NULL,'','','由于安保和版权的原因，大多数演出、展览及比赛场所禁止携带食品、饮料、专业摄录设备、打火机等物品，请您注意现场工作人员和广播的提示，予以配合。','以现场为准,以现场为准',NULL,0,'票品为有价票券，非普通商品，其背后承载的文