--
-- Table structure for table `d_program_category`
--

DROP TABLE IF EXISTS `d_program_category`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `d_program_category` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键id',
  `parent_id` bigint NOT NULL DEFAULT '0' COMMENT '父id',
  `name` varchar(120) NOT NULL COMMENT '名字',
  `type` int NOT NULL DEFAULT '2' COMMENT '1:一级种类 2:二级种类',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `edit_time` datetime NOT NULL COMMENT '编辑时间',
  `status` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1:正常 0:删除',
  PRIMARY KEY (`id`),
  UNIQUE KEY `parent_id_name_type_idx` (`parent_id`,`name`,`type`) USING BTREE,
  KEY `parent_id` (`parent_id`),
  KEY `ctype` (`type`)
) ENGINE=InnoDB AUTO_INCREMENT=22 DEFAULT CHARSET=utf8mb3 COMMENT='节目类型表';
/*!40101 SET character_set_client = @saved_cs_client */;

